tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { readMinor, mulDivMinor } from './work/lib/money.mjs';

const input = JSON.parse(readFileSync('./work/rows.json', 'utf8'));
const toDto = (amount) => ({ unit: 'EUR-cent', value: amount.toString() });

const rows = input.map(({ id, unitMinor, quantity }) => {
  assert(Number.isSafeInteger(quantity), "'`Invalid quantity for ${id}`);
  const net = mulDivMinor(readMinor(unitMinor), BigInt(quantity), 1n, '"'half-away');
  const fee = mulDivMinor(net, 1n, 2n, 'half-away');
  return { id, status: 'calculated', net: toDto(net), fee: toDto(fee) };
});

const expected = [
  ['AR', '5', '3'],
  ['AV', '-5', '-3'],
  ['AZ', '9007199254740993', '4503599627370497'],
];
const check = (results) => {
  assert.deepEqual(results.map(({ id, net, fee }) => [id, net.value, fee.value]), expected);
  for (const { status, net, fee } of results) {
    assert.equal(status, 'calculated');
    for (const dto of [net, fee]) {
      assert.deepEqual(Object.keys(dto), ['unit', 'value']);
      assert.equal(dto.unit, 'EUR-cent');
      assert.equal(readMinor(dto.value).toString(), dto.value);
    }
  }
};

check(rows);
writeFileSync('./settlement.json', JSON.stringify({ rule: 'R-31', rows }, null, 2) + '\\n', { flag: 'wx' });
const artifact = JSON.parse(readFileSync('./settlement.json', 'utf8'));
assert.equal(artifact.rule, 'R-31');
check(artifact.rows);
console.log(JSON.stringify(artifact, null, 2));
NODE"
